# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# D8-form instructions (VLEPEM Rev. 0 Figure A-11).

# CHECK: e_lbzu 3, 0(4) # encoding: [0x18,0x64,0x00,0x00]
e_lbzu 3, 0(4)
# CHECK: e_lbzu 3, -128(4) # encoding: [0x18,0x64,0x00,0x80]
e_lbzu 3, -128(4)
# CHECK: e_lbzu 3, 127(4) # encoding: [0x18,0x64,0x00,0x7f]
e_lbzu 3, 127(4)
# CHECK: e_lhzu 3, 0(4) # encoding: [0x18,0x64,0x01,0x00]
e_lhzu 3, 0(4)
# CHECK: e_lwzu 3, 0(4) # encoding: [0x18,0x64,0x02,0x00]
e_lwzu 3, 0(4)
# CHECK: e_lhau 3, 0(1) # encoding: [0x18,0x61,0x03,0x00]
e_lhau 3, 0(1)
# CHECK: e_stbu 3, -1(4) # encoding: [0x18,0x64,0x04,0xff]
e_stbu 3, -1(4)
# CHECK: e_sthu 3, 0(4) # encoding: [0x18,0x64,0x05,0x00]
e_sthu 3, 0(4)
# CHECK: e_stwu 3, 0(4) # encoding: [0x18,0x64,0x06,0x00]
e_stwu 3, 0(4)
# CHECK: e_lmw 30, -4(1) # encoding: [0x1b,0xc1,0x08,0xfc]
e_lmw 30, -4(1)
# CHECK: e_stmw 3, 0(1) # encoding: [0x18,0x61,0x09,0x00]
e_stmw 3, 0(1)
